// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ValidatorBinding} from "./ValidatorDepositRedeemTypes.sol";

/**
 * @title ValidatorDepositRedeemExitLib
 * @notice External library: full-exit principal payout (EIP-170 offload).
 */
library ValidatorDepositRedeemExitLib {
    event NativeWithdrawn(address indexed to, uint256 amount);
    event FullExitSettled(address indexed beneficiary, uint256 validatorCount, uint256 amount);
    event NodeValidatorExited(uint256 indexed guardianId, bytes32 indexed pubkeyHash, address withdrawalBeneficiary);

    function recordNodeValidatorExit(
        mapping(uint256 => ValidatorBinding) storage nodeValidator,
        uint256 guardianId
    ) external {
        ValidatorBinding storage b = nodeValidator[guardianId];
        require(b.pubkey.length != 0, "ValidatorRedeem: no validator");
        require(b.active, "ValidatorRedeem: already exited");
        b.active = false;
        b.exitedAt = uint64(block.timestamp);
        emit NodeValidatorExited(guardianId, keccak256(b.pubkey), b.withdrawalBeneficiary);
    }

    function settleFullExitPayout(
        mapping(uint256 => address) storage guardianIdBeneficiary,
        mapping(uint256 => ValidatorBinding) storage nodeValidator,
        mapping(bytes32 => bool) storage exitSettledPubkey,
        mapping(address => uint256) storage stakedValidatorCountOf,
        uint256 validatorStakeWei,
        address beneficiary,
        uint256[] calldata guardianIds
    ) external returns (uint256 settledCount) {
        require(beneficiary != address(0), "ValidatorRedeem: zero beneficiary");
        require(guardianIds.length > 0, "ValidatorRedeem: empty");

        for (uint256 i = 0; i < guardianIds.length; i++) {
            uint256 guardianId = guardianIds[i];
            require(guardianIdBeneficiary[guardianId] == beneficiary, "ValidatorRedeem: not beneficiary node");
            ValidatorBinding storage b = nodeValidator[guardianId];
            require(b.pubkey.length != 0, "ValidatorRedeem: no validator");
            require(b.withdrawalBeneficiary == beneficiary, "ValidatorRedeem: beneficiary mismatch");
            require(b.exitedAt != 0, "ValidatorRedeem: exit not requested");
            bytes32 pkHash = keccak256(b.pubkey);
            require(!exitSettledPubkey[pkHash], "ValidatorRedeem: already settled");
            exitSettledPubkey[pkHash] = true;
            settledCount++;
        }

        uint256 amount = validatorStakeWei * settledCount;
        require(address(this).balance >= amount, "ValidatorRedeem: insufficient balance");

        if (stakedValidatorCountOf[beneficiary] >= settledCount) {
            stakedValidatorCountOf[beneficiary] -= settledCount;
        } else {
            stakedValidatorCountOf[beneficiary] = 0;
        }

        (bool ok, ) = payable(beneficiary).call{value: amount}("");
        require(ok, "ValidatorRedeem: native transfer failed");
        emit NativeWithdrawn(beneficiary, amount);
        emit FullExitSettled(beneficiary, settledCount, amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ValidatorBinding} from "./ValidatorDepositRedeemTypes.sol";

interface IBeaconDepositFund {
    function deposit(
        bytes calldata pubkey,
        bytes calldata withdrawal_credentials,
        bytes calldata signature,
        bytes32 deposit_data_root
    ) external payable;
}

/**
 * @title ValidatorDepositRedeemDepositLib
 * @notice External library: fund + deposit validators and register bindings (EIP-170 offload).
 */
library ValidatorDepositRedeemDepositLib {
    event ValidatorDeposited(
        uint256 indexed guardianId,
        address indexed beneficiary,
        bytes32 indexed pubkeyHash,
        uint256 amount
    );
    event NodeValidatorRegistered(
        uint256 indexed guardianId,
        address indexed beneficiary,
        bytes32 indexed pubkeyHash,
        bytes pubkey
    );

    function fundAndDepositValidators(
        address depositContractAddr,
        bytes32 selfCred,
        uint256 validatorStakeWei,
        mapping(uint256 => address) storage guardianIdBeneficiary,
        mapping(uint256 => ValidatorBinding) storage nodeValidator,
        mapping(bytes32 => uint256) storage validatorPubkeyGuardian,
        mapping(address => uint256) storage stakedValidatorCountOf,
        uint256[] calldata guardianIds,
        bytes[] calldata pubkeys,
        bytes[] calldata withdrawalCredentials,
        bytes[] calldata signatures,
        bytes32[] calldata depositDataRoots
    ) external returns (uint256 stakedCountDelta, uint256 fundedDelta) {
        uint256 n = guardianIds.length;
        require(n > 0, "ValidatorRedeem: empty");
        require(
            pubkeys.length == n &&
            withdrawalCredentials.length == n &&
            signatures.length == n &&
            depositDataRoots.length == n,
            "ValidatorRedeem: length mismatch"
        );
        require(depositContractAddr != address(0), "ValidatorRedeem: deposit unset");
        IBeaconDepositFund depositContract = IBeaconDepositFund(depositContractAddr);
        require(address(this).balance >= validatorStakeWei * n, "ValidatorRedeem: insufficient stake balance");

        for (uint256 i = 0; i < n; i++) {
            (uint256 stakedInc, uint256 fundedInc) = _fundOneGuardianDeposit(
                depositContract,
                selfCred,
                validatorStakeWei,
                guardianIdBeneficiary,
                nodeValidator,
                validatorPubkeyGuardian,
                stakedValidatorCountOf,
                guardianIds[i],
                pubkeys[i],
                withdrawalCredentials[i],
                signatures[i],
                depositDataRoots[i]
            );
            stakedCountDelta += stakedInc;
            fundedDelta += fundedInc;
        }
    }

    function _fundOneGuardianDeposit(
        IBeaconDepositFund depositContract,
        bytes32 selfCred,
        uint256 validatorStakeWei,
        mapping(uint256 => address) storage guardianIdBeneficiary,
        mapping(uint256 => ValidatorBinding) storage nodeValidator,
        mapping(bytes32 => uint256) storage validatorPubkeyGuardian,
        mapping(address => uint256) storage stakedValidatorCountOf,
        uint256 guardianId,
        bytes calldata pubkey,
        bytes calldata withdrawalCredentials,
        bytes calldata signature,
        bytes32 depositDataRoot
    ) private returns (uint256 stakedInc, uint256 fundedInc) {
        require(withdrawalCredentials.length == 32, "ValidatorRedeem: bad wc length");
        require(_bytes32FromCalldata(withdrawalCredentials) == selfCred, "ValidatorRedeem: withdrawal not self");

        address beneficiary = guardianIdBeneficiary[guardianId];
        require(beneficiary != address(0), "ValidatorRedeem: node has no beneficiary");

        depositContract.deposit{value: validatorStakeWei}(pubkey, withdrawalCredentials, signature, depositDataRoot);

        _registerOneNodeValidator(nodeValidator, validatorPubkeyGuardian, guardianId, beneficiary, pubkey);
        stakedValidatorCountOf[beneficiary] += 1;
        emit ValidatorDeposited(guardianId, beneficiary, keccak256(pubkey), validatorStakeWei);
        return (1, validatorStakeWei);
    }

    function _registerOneNodeValidator(
        mapping(uint256 => ValidatorBinding) storage nodeValidator,
        mapping(bytes32 => uint256) storage validatorPubkeyGuardian,
        uint256 guardianId,
        address beneficiary,
        bytes calldata pubkey
    ) private {
        require(guardianId != 0, "ValidatorRedeem: zero guardian id");
        require(pubkey.length == 48, "ValidatorRedeem: bad pubkey len");
        bytes32 pkHash = keccak256(pubkey);
        uint256 boundId = validatorPubkeyGuardian[pkHash];
        require(boundId == 0 || boundId == guardianId, "ValidatorRedeem: pubkey bound elsewhere");
        ValidatorBinding storage b = nodeValidator[guardianId];
        require(!b.active || keccak256(b.pubkey) == pkHash, "ValidatorRedeem: node already has active validator");

        b.pubkey = pubkey;
        b.withdrawalBeneficiary = beneficiary;
        b.registeredAt = uint64(block.timestamp);
        b.exitedAt = 0;
        b.active = true;
        validatorPubkeyGuardian[pkHash] = guardianId;

        emit NodeValidatorRegistered(guardianId, beneficiary, pkHash, pubkey);
    }

    function registerOneNodeValidator(
        mapping(uint256 => ValidatorBinding) storage nodeValidator,
        mapping(bytes32 => uint256) storage validatorPubkeyGuardian,
        uint256 guardianId,
        address beneficiary,
        bytes calldata pubkey
    ) external {
        _registerOneNodeValidator(nodeValidator, validatorPubkeyGuardian, guardianId, beneficiary, pubkey);
    }

    function _bytes32FromCalldata(bytes calldata b) private pure returns (bytes32 word) {
        require(b.length == 32, "ValidatorRedeem: bad wc length");
        assembly {
            word := calldataload(b.offset)
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ValidatorBinding} from "./ValidatorDepositRedeemTypes.sol";

interface IGuardianNodesTransferReader {
    function id2ip(uint256 id) external view returns (string memory);
}

interface ITransferMarketGuard {
    function nodeOrder(uint256 guardianId) external view returns (uint256);
}

/**
 * @title ValidatorDepositRedeemTransferLib
 * @notice External library: hot-transfer one Guardian node id between beneficiaries (EIP-170 offload).
 */
library ValidatorDepositRedeemTransferLib {
    event DepinNodeBeneficiaryAssigned(bytes32 indexed ipKey, address indexed beneficiary, string ip);
    event NodeValidatorBeneficiaryUpdated(
        uint256 indexed guardianId,
        bytes32 indexed pubkeyHash,
        address indexed from,
        address to
    );

    function transferOneGuardianId(
        mapping(uint256 => address) storage guardianIdBeneficiary,
        mapping(address => uint256[]) storage beneficiaryGuardianIds,
        mapping(address => address[]) storage beneficiaryGuardianNodeWallets,
        mapping(uint256 => bool) storage guardianIdGbMining,
        mapping(bytes32 => address) storage depinIpBeneficiary,
        mapping(address => address) storage nodeWalletBeneficiary,
        mapping(address => mapping(bytes32 => bool)) storage walletDepinIpSeen,
        mapping(address => string[]) storage walletDepinNodeIps,
        mapping(address => uint256) storage validatorNodeCountOf,
        mapping(address => uint256) storage gbMiningNodeCountOf,
        mapping(address => uint256) storage stakedValidatorCountOf,
        mapping(uint256 => ValidatorBinding) storage nodeValidator,
        address guardianNodes,
        address from,
        address to,
        uint256 guardianId
    ) external {
        _transferOneGuardianId(
            guardianIdBeneficiary,
            beneficiaryGuardianIds,
            beneficiaryGuardianNodeWallets,
            guardianIdGbMining,
            depinIpBeneficiary,
            nodeWalletBeneficiary,
            walletDepinIpSeen,
            walletDepinNodeIps,
            validatorNodeCountOf,
            gbMiningNodeCountOf,
            stakedValidatorCountOf,
            nodeValidator,
            guardianNodes,
            from,
            to,
            guardianId
        );
    }

    function _transferOneGuardianId(
        mapping(uint256 => address) storage guardianIdBeneficiary,
        mapping(address => uint256[]) storage beneficiaryGuardianIds,
        mapping(address => address[]) storage beneficiaryGuardianNodeWallets,
        mapping(uint256 => bool) storage guardianIdGbMining,
        mapping(bytes32 => address) storage depinIpBeneficiary,
        mapping(address => address) storage nodeWalletBeneficiary,
        mapping(address => mapping(bytes32 => bool)) storage walletDepinIpSeen,
        mapping(address => string[]) storage walletDepinNodeIps,
        mapping(address => uint256) storage validatorNodeCountOf,
        mapping(address => uint256) storage gbMiningNodeCountOf,
        mapping(address => uint256) storage stakedValidatorCountOf,
        mapping(uint256 => ValidatorBinding) storage nodeValidator,
        address guardianNodes,
        address from,
        address to,
        uint256 guardianId
    ) internal {
        require(guardianId != 0, "ValidatorRedeem: zero guardian id");
        require(guardianIdBeneficiary[guardianId] == from, "ValidatorRedeem: not from beneficiary node");

        uint256[] storage fromIds = beneficiaryGuardianIds[from];
        address[] storage fromWallets = beneficiaryGuardianNodeWallets[from];
        uint256 len = fromIds.length;
        uint256 idx = type(uint256).max;
        for (uint256 i = 0; i < len; i++) {
            if (fromIds[i] == guardianId) {
                idx = i;
                break;
            }
        }
        require(idx != type(uint256).max, "ValidatorRedeem: node not owned");

        address nodeWallet = fromWallets[idx];

        guardianIdBeneficiary[guardianId] = to;
        beneficiaryGuardianIds[to].push(guardianId);
        beneficiaryGuardianNodeWallets[to].push(nodeWallet);

        uint256 last = len - 1;
        fromIds[idx] = fromIds[last];
        fromWallets[idx] = fromWallets[last];
        fromIds.pop();
        fromWallets.pop();

        if (guardianNodes != address(0)) {
            string memory ip = IGuardianNodesTransferReader(guardianNodes).id2ip(guardianId);
            if (bytes(ip).length != 0) {
                bytes32 ipKey = keccak256(bytes(ip));
                depinIpBeneficiary[ipKey] = to;
                _removeDepinIpFromWallet(walletDepinIpSeen, walletDepinNodeIps, from, ipKey);
                _addDepinIpToWallet(walletDepinIpSeen, walletDepinNodeIps, to, ip, ipKey);
                emit DepinNodeBeneficiaryAssigned(ipKey, to, ip);
            }
        }

        if (nodeWalletBeneficiary[nodeWallet] == from && !_fromStillOwnsWallet(beneficiaryGuardianNodeWallets, from, nodeWallet)) {
            nodeWalletBeneficiary[nodeWallet] = to;
        }
        if (nodeWalletBeneficiary[nodeWallet] == address(0)) {
            nodeWalletBeneficiary[nodeWallet] = to;
        }

        uint256 gbMoved = guardianIdGbMining[guardianId] ? 1 : 0;

        if (validatorNodeCountOf[from] >= 1) {
            validatorNodeCountOf[from] -= 1;
        } else {
            validatorNodeCountOf[from] = 0;
        }
        validatorNodeCountOf[to] += 1;

        if (gbMiningNodeCountOf[from] >= gbMoved) {
            gbMiningNodeCountOf[from] -= gbMoved;
        } else {
            gbMiningNodeCountOf[from] = 0;
        }
        gbMiningNodeCountOf[to] += gbMoved;

        ValidatorBinding storage b = nodeValidator[guardianId];
        if (b.pubkey.length != 0 && b.active) {
            b.withdrawalBeneficiary = to;
            emit NodeValidatorBeneficiaryUpdated(guardianId, keccak256(b.pubkey), from, to);
            if (stakedValidatorCountOf[from] > 0) {
                stakedValidatorCountOf[from] -= 1;
            }
            stakedValidatorCountOf[to] += 1;
        }
    }

    function transferGuardianIdsFrom(
        mapping(uint256 => address) storage guardianIdBeneficiary,
        mapping(address => uint256[]) storage beneficiaryGuardianIds,
        mapping(address => address[]) storage beneficiaryGuardianNodeWallets,
        mapping(uint256 => bool) storage guardianIdGbMining,
        mapping(bytes32 => address) storage depinIpBeneficiary,
        mapping(address => address) storage nodeWalletBeneficiary,
        mapping(address => mapping(bytes32 => bool)) storage walletDepinIpSeen,
        mapping(address => string[]) storage walletDepinNodeIps,
        mapping(address => uint256) storage validatorNodeCountOf,
        mapping(address => uint256) storage gbMiningNodeCountOf,
        mapping(address => uint256) storage stakedValidatorCountOf,
        mapping(uint256 => ValidatorBinding) storage nodeValidator,
        address guardianNodes,
        address transferMarket,
        address fromBeneficiary,
        address toBeneficiary,
        uint256[] calldata guardianIds
    ) external {
        require(toBeneficiary != address(0), "ValidatorRedeem: zero to beneficiary");
        require(toBeneficiary != fromBeneficiary, "ValidatorRedeem: same beneficiary");
        require(guardianIds.length > 0, "ValidatorRedeem: empty");
        for (uint256 i = 0; i < guardianIds.length; i++) {
            if (transferMarket != address(0)) {
                require(
                    ITransferMarketGuard(transferMarket).nodeOrder(guardianIds[i]) == 0,
                    "ValidatorRedeem: node listed in order"
                );
            }
            _transferOneGuardianId(
                guardianIdBeneficiary,
                beneficiaryGuardianIds,
                beneficiaryGuardianNodeWallets,
                guardianIdGbMining,
                depinIpBeneficiary,
                nodeWalletBeneficiary,
                walletDepinIpSeen,
                walletDepinNodeIps,
                validatorNodeCountOf,
                gbMiningNodeCountOf,
                stakedValidatorCountOf,
                nodeValidator,
                guardianNodes,
                fromBeneficiary,
                toBeneficiary,
                guardianIds[i]
            );
        }
    }

    function _fromStillOwnsWallet(
        mapping(address => address[]) storage beneficiaryGuardianNodeWallets,
        address from,
        address nodeWallet
    ) private view returns (bool) {
        address[] storage wallets = beneficiaryGuardianNodeWallets[from];
        for (uint256 i = 0; i < wallets.length; i++) {
            if (wallets[i] == nodeWallet) return true;
        }
        return false;
    }

    function _removeDepinIpFromWallet(
        mapping(address => mapping(bytes32 => bool)) storage walletDepinIpSeen,
        mapping(address => string[]) storage walletDepinNodeIps,
        address beneficiary,
        bytes32 ipKey
    ) private {
        if (!walletDepinIpSeen[beneficiary][ipKey]) return;
        walletDepinIpSeen[beneficiary][ipKey] = false;
        string[] storage arr = walletDepinNodeIps[beneficiary];
        for (uint256 i = 0; i < arr.length; i++) {
            if (keccak256(bytes(arr[i])) == ipKey) {
                arr[i] = arr[arr.length - 1];
                arr.pop();
                break;
            }
        }
    }

    function _addDepinIpToWallet(
        mapping(address => mapping(bytes32 => bool)) storage walletDepinIpSeen,
        mapping(address => string[]) storage walletDepinNodeIps,
        address beneficiary,
        string memory ip,
        bytes32 ipKey
    ) private {
        if (walletDepinIpSeen[beneficiary][ipKey]) return;
        walletDepinIpSeen[beneficiary][ipKey] = true;
        walletDepinNodeIps[beneficiary].push(ip);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {NodeBundle} from "./ValidatorDepositRedeemTypes.sol";

interface IGuardianNodesBundleReader {
    function id2ip(uint256 id) external view returns (string memory);
    function idOwner(uint256 id) external view returns (address);
    function ipaddress2owner(string memory ipaddress) external view returns (address);
}

interface IERC1155BundleBalance {
    function balanceOf(address account, uint256 id) external view returns (uint256);
}

interface IERC20BundleBalance {
    function balanceOf(address account) external view returns (uint256);
}

/// @dev Read-only bundle assembly callbacks on {ValidatorDepositRedeem}.
interface IRedeemBundleStorageReader {
    function nodeValidatorBinding(uint256 guardianId)
        external
        view
        returns (bytes memory pubkey, bool active);
    function validatorNodeCountOf(address beneficiary) external view returns (uint256);
    function gbMiningNodeCountOf(address beneficiary) external view returns (uint256);
    function walletClaimCountOf(address beneficiary) external view returns (uint256);
}

/**
 * @title ValidatorDepositRedeemBundleLib
 * @notice External library: assemble {NodeBundle} for RPC reads. Linked from {ValidatorDepositRedeem}.
 */
library ValidatorDepositRedeemBundleLib {
    uint256 internal constant GB_NET_TOTAL_ID = 0;

    function buildNodeBundle(
        address host,
        address guardianNodesAddr,
        address gbTokenAddr,
        address usdcTokenAddr,
        address beneficiary,
        uint256[] memory ids
    ) external view returns (NodeBundle memory b) {
        b.beneficiary = beneficiary;
        if (beneficiary == address(0)) {
            b.guardianNodeIds = new uint256[](0);
            b.depinNodeIps = new string[](0);
            b.nodeWallets = new address[](0);
            b.validatorPubkeys = new bytes[](0);
            b.validatorActive = new bool[](0);
            return b;
        }

        IRedeemBundleStorageReader reader = IRedeemBundleStorageReader(host);
        uint256 n = ids.length;
        b.guardianNodeIds = ids;
        b.depinNodeIps = new string[](n);
        b.nodeWallets = new address[](n);
        b.validatorPubkeys = new bytes[](n);
        b.validatorActive = new bool[](n);

        IGuardianNodesBundleReader guardian = IGuardianNodesBundleReader(guardianNodesAddr);
        if (guardianNodesAddr != address(0)) {
            for (uint256 i = 0; i < n; i++) {
                uint256 nodeId = ids[i];
                string memory ip = guardian.id2ip(nodeId);
                b.depinNodeIps[i] = ip;
                address w = guardian.idOwner(nodeId);
                if (w == address(0) && bytes(ip).length != 0) {
                    w = guardian.ipaddress2owner(ip);
                }
                b.nodeWallets[i] = w;
                (bytes memory pk, bool active) = reader.nodeValidatorBinding(nodeId);
                b.validatorPubkeys[i] = pk;
                b.validatorActive[i] = active;
            }
        }

        b.validatorNodeCount = reader.validatorNodeCountOf(beneficiary);
        b.gbMiningNodeCount = reader.gbMiningNodeCountOf(beneficiary);
        b.claimCount = reader.walletClaimCountOf(beneficiary);
        b.nativeBalance = beneficiary.balance;
        b.gbBalance = _safeGbBalance(gbTokenAddr, beneficiary);
        b.usdcBalance = _safeUsdcBalance(usdcTokenAddr, beneficiary);
    }

    function _safeGbBalance(address gbToken, address wallet) private view returns (uint256) {
        if (gbToken == address(0)) return 0;
        try IERC1155BundleBalance(gbToken).balanceOf(wallet, GB_NET_TOTAL_ID) returns (uint256 bal) {
            return bal;
        } catch {
            return 0;
        }
    }

    function _safeUsdcBalance(address usdcToken, address wallet) private view returns (uint256) {
        if (usdcToken == address(0)) return 0;
        try IERC20BundleBalance(usdcToken).balanceOf(wallet) returns (uint256 bal) {
            return bal;
        } catch {
            return 0;
        }
    }
}

